/**
 * @file src/lib/questSnapshot.ts
 * Read-only snapshot for QuestPanel Svelte list.
 */

import type { GameRuntime } from '../types/game.js';
import type {
  QuestCardSnapshot,
  QuestCardStructured,
  QuestPanelUiSnapshot,
  QuestSectionHeaderSnapshot,
  QuestSectionSnapshot,
  QuestsSnapshot,
  QuestRewardLine,
} from '../bus/snapshots.js';
import { publish } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import { questsSnapshotWouldChange } from '../stores/questSnapshotDiff.js';
import {
  Quest,
  buildQuestCardHTML,
  getQuestRepeatBadgeDisplay,
  questUiText,
  getQuestDisplayTitle,
  getQuestDisplayDescription,
  getQuestDisplayDialogue,
  getQuestDisplayDescriptionHtml,
  getQuestDisplayDialogueHtml,
  getSafeQuestActionId,
  getScaledQuestTokenReward,
  getQuestLocalizedItemName,
  formatQuestProgressNumber,
} from '@snapshot/quest';
import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.js';
import { KEY_ITEMS } from '../../constants/balance/consumablesItems.ts';
import { getItemIconHTML } from '../ui/utils.ts';
import { getWeeklyChallengesSnapshot } from '@snapshot-deps/weekly';
import { CHEN_SPRITE_URL } from '../../narrativeData.ts';
import { formatNumber } from '../../formatters.ts';
import { questRewardTooltipTitle } from './questRewardTooltips.ts';

function buildQuestCardStructured(
  game: GameRuntime,
  quest: Quest,
  fullHtml?: string,
): QuestCardStructured {
  const toSafeInt = (value: unknown) => Math.max(0, Math.floor(Number(value) || 0));
  const current = toSafeInt(quest.current);
  const target = Math.max(1, toSafeInt(quest.target) || 1);
  const percent = Math.min(100, (current / target) * 100);
  const safeQuestId = getSafeQuestActionId(quest.id);

  let badgeClass = 'badge-easy';
  let badgeText = questUiText(game, 'badgeEasy', 'Facile');
  if (quest.questType === 'STORY') {
    badgeClass = 'badge-extreme';
    badgeText = questUiText(game, 'badgeStory', 'Scenario');
  } else if (quest.questType === 'TEAM_ROCKET') {
    badgeClass = 'badge-hard';
    badgeText = 'Team Rocket';
  } else {
    if (quest.difficulty === 'MEDIUM') {
      badgeClass = 'badge-medium';
      badgeText = questUiText(game, 'badgeMedium', 'Moyen');
    }
    if (quest.difficulty === 'HARD') {
      badgeClass = 'badge-hard';
      badgeText = questUiText(game, 'badgeHard', 'Difficile');
    }
    if (quest.difficulty === 'EXTREME') {
      badgeClass = 'badge-extreme';
      badgeText = questUiText(game, 'badgeExtreme', 'Extreme');
    }
  }

  const rewards: QuestRewardLine[] = [];
  if (quest.rewards) {
    const pd = Number(quest.rewards.pokedollars || 0);
    if (pd > 0) {
      rewards.push({
        key: 'pd',
        text: formatNumber(pd),
        img: 'img/pokedollars.png',
        tooltipTitle: questRewardTooltipTitle(game, 'pokedollars'),
      });
    }
    const tokenReward = getScaledQuestTokenReward(game, quest.rewards);
    if (tokenReward > 0) {
      rewards.push({
        key: 'token',
        text: String(tokenReward),
        img: 'https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/magma-emblem.png',
        imgClass: 'quest-token-inline',
        tooltipTitle: questRewardTooltipTitle(game, 'questTokens'),
      });
    }
    const talentRerolls = Math.max(0, Math.floor(Number(quest.rewards.talentRerolls) || 0));
    if (talentRerolls > 0) {
      const talentRerollDef = (KEY_ITEMS as Record<string, Record<string, unknown>>)['talent_reroll'];
      rewards.push({
        key: 'talent-reroll',
        text: String(talentRerolls),
        img: 'img/talent-reroll.png',
        tooltipTitle: getQuestLocalizedItemName(game, 'talent_reroll', talentRerollDef),
      });
    }
    const talentChoices = Math.max(0, Math.floor(Number(quest.rewards.talentChoices) || 0));
    if (talentChoices > 0) {
      const talentChoiceDef = (KEY_ITEMS as Record<string, Record<string, unknown>>)['talent_choice'];
      rewards.push({
        key: 'talent-choice',
        text: String(talentChoices),
        img: 'img/ability-patch.png',
        tooltipTitle: getQuestLocalizedItemName(game, 'talent_choice', talentChoiceDef),
      });
    }
    if (quest.rewards.items) {
      for (const [key, count] of Object.entries(quest.rewards.items)) {
        const safeCount = Math.max(0, Math.floor(Number(count) || 0));
        if (safeCount <= 0) continue;
        const itemDef = (ALL_ITEMS as Record<string, Record<string, unknown>>)[key]
          ?? (KEY_ITEMS as Record<string, Record<string, unknown>>)[key]
          ?? { name: key };
        const iconHTML = getItemIconHTML(itemDef);
        const itemName = getQuestLocalizedItemName(game, key, itemDef);
        rewards.push({
          key: `item-${key}`,
          icon: iconHTML,
          text: `${safeCount}x ${itemName || key}`,
          tooltipTitle: itemName || key,
        });
      }
    }
    const eggSpriteByRarity: Record<string, string> = {
      common: 'img/common-egg.png',
      rare: 'img/rare-egg.png',
      epic: 'img/epic-egg.png',
      legendary: 'img/legendary-egg.png',
    };
    if (quest.rewards.eggs) {
      for (const [rarity, count] of Object.entries(quest.rewards.eggs)) {
        const safeCount = Math.max(0, Math.floor(Number(count) || 0));
        if (safeCount <= 0) continue;
        const rarityKey = String(rarity || '').toLowerCase();
        const eggSprite = eggSpriteByRarity[rarityKey] || eggSpriteByRarity.common;
        const eggLabel = questUiText(game, 'rewardEggLabel', 'Oeuf');
        rewards.push({
          key: `egg-${rarityKey}`,
          text: `${safeCount}x ${eggLabel} ${rarityKey}`,
          img: eggSprite,
          imgClass: 'quest-reward-inline-img quest-reward-egg',
          tooltipTitle: `${eggLabel} ${rarityKey}`,
        });
      }
    }
    const autoSlots = Math.max(
      0,
      Math.floor(Number(quest.rewards.unlocks?.autoIncubatorSlots) || 0),
    );
    if (autoSlots > 0) {
      const autoLabel = questUiText(game, 'rewardAutoIncubatorLabel', 'incubateur auto');
      rewards.push({
        key: 'auto-incubator',
        text: `+${autoSlots} ${autoLabel}`,
        tooltipTitle: autoLabel,
      });
    }
  }

  const actions: QuestCardStructured['actions'] = {};
  if (!safeQuestId) {
    actions.invalid = questUiText(
      game,
      'invalidQuestData',
      'Quest data invalid - action disabled.',
    );
  } else if (!quest.accepted) {
    actions.accept = questUiText(game, 'accept', 'Accepter');
    actions.refuse = questUiText(game, 'refuse', 'Refuser');
  } else if (quest.completed) {
    actions.claim = questUiText(game, 'claim', 'Recuperer');
  } else if (quest.questType !== 'STORY' && quest.questType !== 'TEAM_ROCKET') {
    actions.abandon = questUiText(game, 'abandon', 'Abandonner');
  } else {
    actions.storyNote = questUiText(
      game,
      'storyNotAbandonable',
      'Quete scenario - non abandonnable',
    );
  }

  const dialogue = getQuestDisplayDialogue(game, quest);
  const description = getQuestDisplayDescription(game, quest);
  const descriptionHtml = getQuestDisplayDescriptionHtml(game, quest);
  const dialogueHtml = getQuestDisplayDialogueHtml(game, quest);
  const repeatBadge = getQuestRepeatBadgeDisplay(game, quest);

  const html = fullHtml ?? buildQuestCardHTML(game, quest);
  let extraHtml: string | undefined;
  const extraStart = html.indexOf('<!-- quest-extra -->');
  const extraEnd = html.indexOf('<!-- /quest-extra -->');
  if (extraStart >= 0 && extraEnd > extraStart) {
    extraHtml = html
      .slice(extraStart + '<!-- quest-extra -->'.length, extraEnd)
      .trim();
  }

  return {
    questId: String(quest.id),
    badgeClass,
    badgeText,
    title: getQuestDisplayTitle(game, quest),
    description,
    descriptionHtml,
    dialogue: dialogue && dialogue !== description ? dialogue : undefined,
    dialogueHtml: dialogueHtml && dialogue && dialogue !== description ? dialogueHtml : undefined,
    current,
    target,
    progressText: `${formatQuestProgressNumber(quest, current)} / ${formatQuestProgressNumber(quest, target)}`,
    percent,
    rewards,
    actions,
    extraHtml,
    repeatBadgeText: repeatBadge?.text,
    repeatBadgeTitle: repeatBadge?.title,
  };
}

function toQuestCard(
  game: GameRuntime,
  quest: Quest,
  extraClass = '',
  borderLeft = '',
): QuestCardSnapshot {
  const classes = ['quest-card', extraClass];
  if (quest.accepted && !quest.completed) classes.push('accepted');
  if (quest.completed) classes.push('completed');
  const cardHtml = buildQuestCardHTML(game, quest);
  return {
    questId: String(quest.id),
    cardHtml,
    structured: buildQuestCardStructured(game, quest, cardHtml),
    cardClass: classes.filter(Boolean).join(' '),
    borderLeft: borderLeft || undefined,
  };
}

function storyHeader(game: GameRuntime): QuestSectionHeaderSnapshot {
  return {
    iconUrl: CHEN_SPRITE_URL,
    iconAlt: 'Chen',
    fallbackEmoji: '👨‍🔬',
    title: questUiText(game, 'storySectionTitle', 'Quetes du Professeur Chen'),
    description: questUiText(
      game,
      'storySectionDesc',
      'Objectifs scenario a ne pas louper.',
    ),
  };
}

function questPanelT(game: GameRuntime, key: string, fallback: string): string {
  if (typeof game.t === 'function') {
    const translated = game.t(key);
    if (translated && translated !== key) return translated;
  }
  return fallback;
}

function buildQuestPanelUi(game: GameRuntime): QuestPanelUiSnapshot {
  const language =
    game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : 'fr';
  return {
    language,
    subTabQuests: questPanelT(game, 'tabs.quests', 'Quêtes'),
    subTabAchievements: questPanelT(game, 'quests.subTabAchievements', 'Succès'),
    dailyTitle: questPanelT(game, 'quests.dailyTitle', 'Quêtes du Jour'),
    nextLabel: questPanelT(game, 'quests.nextLabel', 'Prochaine :'),
    achievementsTitle: questPanelT(game, 'quests.achievementsTitle', 'Succès Permanents'),
    subTabsAriaLabel: questPanelT(game, 'quests.subTabsAriaLabel', 'Sous-sections quêtes'),
  };
}

function rocketHeader(game: GameRuntime): QuestSectionHeaderSnapshot {
  return {
    iconUrl: 'img/logo-rocket.png',
    iconAlt: 'Team Rocket',
    fallbackEmoji: '🚀',
    title: questUiText(game, 'rocketSectionTitle', 'Missions Team Rocket'),
    description: questUiText(
      game,
      'rocketSectionDesc',
      'Objectifs speciaux de la faction Rocket.',
    ),
  };
}

export function buildQuestsSnapshot(game: GameRuntime): QuestsSnapshot {
  const ui = buildQuestPanelUi(game);
  const classicUnlocked = !!(game.unlockedFeatures && game.unlockedFeatures.classicQuests);
  const rocketUnlocked = !!(game.unlockedFeatures && game.unlockedFeatures.teamRocketTab);
  const weeklySection = getWeeklyChallengesSnapshot(game);

  const displayableQuests = (game.quests as unknown as Quest[]).filter((q) => !q.claimed);
  const storyQuests = displayableQuests.filter((q) => q.questType === 'STORY');
  const teamRocketQuests = displayableQuests.filter((q) => q.questType === 'TEAM_ROCKET');
  const otherQuests = displayableQuests.filter(
    (q) => q.questType !== 'STORY' && q.questType !== 'TEAM_ROCKET',
  );
  const orderedOtherQuests = otherQuests.slice().reverse();

  if (game.quests.length === 0) {
    return {
      ui,
      emptyMessage: questUiText(
        game,
        'noQuestAvailable',
        'Aucune quete disponible.<br>Revenez plus tard !',
      ),
      storySection: null,
      rocketSection: null,
      weeklySection,
      classicQuests: [],
      classicQuestsUnlocked: classicUnlocked,
      rocketUnlocked,
      questCount: 0,
      questTokens: game.questTokens || 0,
      questsCompleted: game.questsCompleted || 0,
    };
  }

  let storySection: QuestSectionSnapshot | null = null;
  if (storyQuests.length > 0) {
    storySection = {
      visible: true,
      header: storyHeader(game),
      quests: storyQuests.map((q) =>
        toQuestCard(game, q, 'quest-card-story', '4px solid #f59e0b'),
      ),
    };
  }

  let rocketSection: QuestSectionSnapshot | null = null;
  if (teamRocketQuests.length > 0) {
    rocketSection = {
      unlockKey: 'teamRocketTab',
      visible: rocketUnlocked,
      header: rocketHeader(game),
      quests: teamRocketQuests.map((q) =>
        toQuestCard(game, q, 'quest-card-story', '4px solid #ef4444'),
      ),
    };
  }

  const classicQuests = orderedOtherQuests.map((q) => toQuestCard(game, q));

  return {
    ui,
    emptyMessage: null,
    storySection,
    rocketSection,
    weeklySection,
    classicQuests,
    classicQuestsUnlocked: classicUnlocked,
    rocketUnlocked,
    questCount: otherQuests.length,
    questTokens: game.questTokens || 0,
    questsCompleted: game.questsCompleted || 0,
  };
}

let lastQuestsSnapshot: QuestsSnapshot | null = null;

/** @internal Vitest only */
export function resetQuestsSnapshotDedupForTests(): void {
  lastQuestsSnapshot = null;
}

/** Build snapshot and publish QUESTS_CHANGED (deduped). */
export function notifyQuestsChanged(game: GameRuntime): void {
  const quests = buildQuestsSnapshot(game);
  if (lastQuestsSnapshot && !questsSnapshotWouldChange(lastQuestsSnapshot, quests)) return;
  lastQuestsSnapshot = quests;
  publish({ type: Evt.QUESTS_CHANGED, quests });
}
