/**
 * @file src/stores/questSnapshotDiff.ts
 * Pure comparison for QUESTS_CHANGED publish deduplication.
 */

import type { QuestCardSnapshot, QuestsSnapshot } from '../bus/snapshots.js';

function cardEqual(a: QuestCardSnapshot, b: QuestCardSnapshot): boolean {
  return (
    a.questId === b.questId
    && a.cardClass === b.cardClass
    && a.borderLeft === b.borderLeft
    && a.cardHtml === b.cardHtml
    && JSON.stringify(a.structured) === JSON.stringify(b.structured)
  );
}

function sectionEqual(
  a: QuestsSnapshot['storySection'],
  b: QuestsSnapshot['storySection'],
): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  if (a.visible !== b.visible) return false;
  if (JSON.stringify(a.header) !== JSON.stringify(b.header)) return false;
  if (a.quests.length !== b.quests.length) return false;
  for (let i = 0; i < a.quests.length; i++) {
    const aq = a.quests[i];
    const bq = b.quests[i];
    if (aq === undefined || bq === undefined) return false;
    if (!cardEqual(aq, bq)) return false;
  }
  return true;
}

function cardsEqual(a: QuestsSnapshot['classicQuests'], b: QuestsSnapshot['classicQuests']): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const ai = a[i];
    const bi = b[i];
    if (ai === undefined || bi === undefined) return false;
    if (!cardEqual(ai, bi)) return false;
  }
  return true;
}

function weeklyEqual(a: QuestsSnapshot['weeklySection'], b: QuestsSnapshot['weeklySection']): boolean {
  if (a.weekKey !== b.weekKey || a.unlocked !== b.unlocked) return false;
  if (a.sectionTitle !== b.sectionTitle || a.sectionDesc !== b.sectionDesc) return false;
  if (a.challenges.length !== b.challenges.length) return false;
  for (let i = 0; i < a.challenges.length; i++) {
    const ac = a.challenges[i];
    const bc = b.challenges[i];
    if (!ac || !bc) return false;
    if (ac.id !== bc.id || ac.cardClass !== bc.cardClass || ac.cardHtml !== bc.cardHtml) return false;
  }
  return true;
}

function uiEqual(a: QuestsSnapshot['ui'], b: QuestsSnapshot['ui']): boolean {
  return (
    a.language === b.language
    && a.subTabQuests === b.subTabQuests
    && a.subTabAchievements === b.subTabAchievements
    && a.dailyTitle === b.dailyTitle
    && a.nextLabel === b.nextLabel
    && a.achievementsTitle === b.achievementsTitle
    && a.subTabsAriaLabel === b.subTabsAriaLabel
  );
}

export function questsSnapshotWouldChange(prev: QuestsSnapshot, next: QuestsSnapshot): boolean {
  return (
    !uiEqual(prev.ui, next.ui)
    || prev.emptyMessage !== next.emptyMessage
    || prev.questCount !== next.questCount
    || prev.questTokens !== next.questTokens
    || prev.questsCompleted !== next.questsCompleted
    || prev.classicQuestsUnlocked !== next.classicQuestsUnlocked
    || prev.rocketUnlocked !== next.rocketUnlocked
    || !sectionEqual(prev.storySection, next.storySection)
    || !sectionEqual(prev.rocketSection, next.rocketSection)
    || !weeklyEqual(prev.weeklySection, next.weeklySection)
    || !cardsEqual(prev.classicQuests, next.classicQuests)
  );
}
